import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents rounds half to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
});

test('roundCents ignores binary noise', () => {
  assert.equal(roundCents(124.49999999999999), 124);
});

test('formatEuros adds the sign, thousands separators and two decimals', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
});

test('parseEuros reads what people type', () => {
  const r = parseEuros('12.5');
  assert.equal(r.ok, true);
  assert.equal(r.value, 1250);
});

test('RATES has EUR USD and GBP', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert returns ok for valid currencies', () => {
  const r = convert(100, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, 100);
});

test('convert EUR to EUR returns same amount', () => {
  const r = convert(1000, 'EUR');
  assert.equal(r.value, 1000);
});

test('convert EUR to USD uses correct rate', () => {
  const r = convert(10000, 'USD');
  assert.equal(r.value, 10850);
});

test('convert EUR to GBP uses correct rate', () => {
  const r = convert(10000, 'GBP');
  assert.equal(r.value, 8425);
});

test('convert rounds the result', () => {
  const r = convert(1, 'USD');
  assert.equal(r.value, Math.round(1 * 1.085));
});

test('convert returns fail for unknown currency', () => {
  const r = convert(100, 'JPY');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'UNKNOWN_CURRENCY');
});

test('convert handles negative amounts', () => {
  const r = convert(-10000, 'USD');
  assert.equal(r.value, -10850);
});

test('convert handles zero', () => {
  const r = convert(0, 'USD');
  assert.equal(r.value, 0);
});

test('formatMoney uses € for EUR', () => {
  const formatted = formatMoney(123456, 'EUR');
  assert(formatted.includes('€'));
});

test('formatMoney uses $ for USD', () => {
  const formatted = formatMoney(123456, 'USD');
  assert(formatted.includes('$'));
  assert(!formatted.includes('€'));
});

test('formatMoney uses £ for GBP', () => {
  const formatted = formatMoney(123456, 'GBP');
  assert(formatted.includes('£'));
  assert(!formatted.includes('€'));
});

test('formatMoney formats USD correctly', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
});

test('formatMoney formats GBP correctly', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
});

test('formatMoney formats EUR correctly', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney handles negative amounts', () => {
  const formatted = formatMoney(-100, 'USD');
  assert(formatted.startsWith('-'));
  assert(formatted.includes('$'));
});

test('formatMoney formats single digit cents', () => {
  assert.equal(formatMoney(105, 'USD'), '$1.05');
});

test('formatMoney formats zero', () => {
  assert.equal(formatMoney(0, 'USD'), '$0.00');
});

test('formatMoney uses thousands separator', () => {
  const formatted = formatMoney(10000000, 'USD');
  assert(formatted.includes(','));
});

test('convert followed by formatMoney preserves value for EUR', () => {
  const converted = convert(123456, 'EUR');
  const formatted = formatMoney(converted.value, 'EUR');
  assert.equal(formatted, '€1,234.56');
});

test('convert EUR cents to USD and format', () => {
  const usdCents = convert(10000, 'USD');
  const formatted = formatMoney(usdCents.value, 'USD');
  assert.equal(formatted, '$108.50');
});

test('convert EUR cents to GBP and format', () => {
  const gbpCents = convert(10000, 'GBP');
  const formatted = formatMoney(gbpCents.value, 'GBP');
  assert.equal(formatted, '£84.25');
});

